(window.RW_DISPLAY = window.RW_DISPLAY || {})["words-in-context_13"] = [{"id":"571cf537","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Hard","context":"Craft and Structure · Words in Context","passage":"The author’s claim about the relationship between Neanderthals and Homo sapiens is ______, as it fails to account for several recent archaeological discoveries. To be convincing, his argument would need to address recent finds of additional hominid fossils, such as the latest Denisovan specimens and Homo longi.","passage_lines":[{"type":"line","text":"The author’s claim about the relationship between Neanderthals and Homo sapiens is ______, as it fails to account for several recent","indent":0},{"type":"line","text":"archaeological discoveries. To be convincing, his argument would need to address recent finds of additional hominid fossils, such as the latest","indent":0},{"type":"line","text":"Denisovan specimens and Homo longi.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["disorienting","tenuous","nuanced","unoriginal"]},{"id":"8a47383f","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Easy","context":"Craft and Structure · Words in Context","passage":"The National Heritage Fellowship was created to publicly ______ exceptional folk and traditional artists in the United States. In 2015, the fellowship was given to the circus aerialist (mid-air acrobat) Dolly Jacobs to celebrate her lifetime contributions to the arts.","passage_lines":[{"type":"line","text":"The National Heritage Fellowship was created to publicly ______ exceptional folk and traditional artists in the United States. In 2015, the","indent":0},{"type":"line","text":"fellowship was given to the circus aerialist (mid-air acrobat) Dolly Jacobs to celebrate her lifetime contributions to the arts.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["startle","recognize","familiarize","convey"]},{"id":"359b891c","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Easy","context":"Craft and Structure · Words in Context","passage":"Painter Alma W. Thomas was fascinated by the colors and shapes found in nature. The flowers and trees in the garden at her home in Washington, DC, ______ her work. For example, Thomas’s use of broken brushstrokes was inspired by the way that light would shine through the leaves of a tree in front of her house.","passage_lines":[{"type":"line","text":"Painter Alma W. Thomas was fascinated by the colors and shapes found in nature. The flowers and trees in the garden at her home in","indent":0},{"type":"line","text":"Washington, DC, ______ her work. For example, Thomas’s use of broken brushstrokes was inspired by the way that light would shine through the","indent":0},{"type":"line","text":"leaves of a tree in front of her house.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["restricted","announced","distracted","influenced"]},{"id":"e37b9e34","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Medium","context":"Craft and Structure · Words in Context","passage":"Some researchers believe that the genes that enable groundhogs and certain other mammals to hibernate through the winter by slowing their breathing and heart rates and lowering their body temperature may be ______ in humans: present yet having essentially no effect on our bodily processes.","passage_lines":[{"type":"line","text":"Some researchers believe that the genes that enable groundhogs and certain other mammals to hibernate through the winter by slowing their","indent":0},{"type":"line","text":"breathing and heart rates and lowering their body temperature may be ______ in humans: present yet having essentially no effect on our bodily","indent":0},{"type":"line","text":"processes.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["decisive","lacking","variable","dormant"]},{"id":"52fe862a","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Easy","context":"Craft and Structure · Words in Context","passage":"Researcher Lucy Salazar is using radiocarbon dating to study Machu Picchu, an ancient Incan fortress in the Andes Mountains. She and her colleagues have found that the site’s age differs from the ______ estimate: it is approximately 20 years older than scholars thought when first encountering Machu Picchu in 1911.","passage_lines":[{"type":"line","text":"Researcher Lucy Salazar is using radiocarbon dating to study Machu Picchu, an ancient Incan fortress in the Andes Mountains. She and her","indent":0},{"type":"line","text":"colleagues have found that the site’s age differs from the ______ estimate: it is approximately 20 years older than scholars thought when first","indent":0},{"type":"line","text":"encountering Machu Picchu in 1911.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["genuine","intentional","independent","original"]},{"id":"f773a56b","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Easy","context":"Craft and Structure · Words in Context","passage":"As Mexico’s first president from an Indigenous community, Benito Juarez became one of the most ______ figures in his country’s history: among the many significant accomplishments of his long tenure in office (1858 – 1872), Juarez consolidated the authority of the national government and advanced the rights of Indigenous peoples.","question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["unpredictable","important","secretive","ordinary"]},{"id":"c14daa3c","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Hard","context":"Craft and Structure · Words in Context","passage":"Close analysis of the painting Girl with a Flute, long attributed to the seventeenth-century Dutch painter Johannes Vermeer, has revealed subtle deviations from the artist’s signature techniques. These variations suggest that the work may be that of a student under Vermeer’s tutelage — potentially ______ our understanding of Vermeer as a solitary artist.","passage_lines":[{"type":"line","text":"Close analysis of the painting Girl with a Flute, long attributed to the seventeenth-century Dutch painter Johannes Vermeer, has revealed subtle","indent":0},{"type":"line","text":"deviations from the artist’s signature techniques. These variations suggest that the work may be that of a student under Vermeer’s tutelage—","indent":0},{"type":"line","text":"potentially ______ our understanding of Vermeer as a solitary artist.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["negating","prefiguring","entrenching","substantiating"]},{"id":"74ee7737","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Easy","context":"Craft and Structure · Words in Context","passage":"Whether Carmen Lomas Garza is creating small paintings and illustrations or large public artworks —such as Baile, a copper cutout of traditional Mexican dance in the San Francisco International Airport — she is ______ direct experience, drawing from memories of her childhood in Texas or details of her current surroundings in California.","passage_lines":[{"type":"line","text":"Whether Carmen Lomas Garza is creating small paintings and illustrations or large public artworks—such as Baile, a copper cutout of traditional","indent":0},{"type":"line","text":"Mexican dance in the San Francisco International Airport—she is ______ direct experience, drawing from memories of her childhood in Texas or","indent":0},{"type":"line","text":"details of her current surroundings in California.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["complimented by","uncertain about","unbothered by","inspired by"]},{"id":"6286dd96","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Easy","context":"Craft and Structure · Words in Context","passage":"The following text is adapted from Frances Hodgson Burnett’s 1905 novel A Little Princess. Sara is a young student at a school in London. Sara not only could tell stories, but she adored telling them. When she sat or stood in the midst of a circle and began to invent wonderful things, her green eyes grew big and shining, her cheeks flushed, and, without knowing that she was doing it, she began to act and made what she told lovely or alarming by the raising or dropping of her voice. As used in the text,","passage_lines":[{"type":"line","text":"The following text is adapted from Frances Hodgson Burnett’s 1905 novel A Little Princess. Sara is a young student at a school in London.","indent":0},{"type":"line","text":"Sara not only could tell stories, but she adored telling them. When she sat or stood in the midst of a circle and began to invent","indent":2},{"type":"line","text":"wonderful things, her green eyes grew big and shining, her cheeks flushed, and, without knowing that she was doing it, she began","indent":2},{"type":"blank"},{"type":"line","text":"to act and made what she told lovely or alarming by the raising or dropping of her voice.","indent":2}],"question":"As used in the text, what does the word “invent” most nearly mean?","choices":["Mislead","Disguise","Create","Discover"],"underline":"invent","underline_segments":["invent"]},{"id":"6c086e70","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Hard","context":"Craft and Structure · Words in Context","passage":"Businesses typically try to promote themselves, but research by Michael Luca, Abhishek Nagaraj, and Gauri Subramani suggests that some do not ______ their marketing. The researchers studied restaurants in Texas and found that those listed on a popular review website (which can be done at no cost) had revenue increases of 5 percent on average, but 33 percent of restaurants studied never listed on the site.","passage_lines":[{"type":"line","text":"Businesses typically try to promote themselves, but research by Michael Luca, Abhishek Nagaraj, and Gauri Subramani suggests that some do","indent":0},{"type":"line","text":"not ______ their marketing. The researchers studied restaurants in Texas and found that those listed on a popular review website (which can be","indent":0},{"type":"line","text":"done at no cost) had revenue increases of 5 percent on average, but 33 percent of restaurants studied never listed on the site.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["adorn","optimize","endorse","counteract"]},{"id":"1107e7dc","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Medium","context":"Craft and Structure · Words in Context","passage":"Economists often assert that countries looking to increase their reliance on solar energy should expand their capacity for storage; having an ample reserve of stored energy can mitigate the effects of ______ solar energy collection caused by unpredictable shifts in cloud cover and haze.","passage_lines":[{"type":"line","text":"Economists often assert that countries looking to increase their reliance on solar energy should expand their capacity for storage; having an","indent":0},{"type":"line","text":"ample reserve of stored energy can mitigate the effects of ______ solar energy collection caused by unpredictable shifts in cloud cover and haze.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["developments of","fluctuations in","calibrations with","incentives for"]},{"id":"dc234d74","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Medium","context":"Craft and Structure · Words in Context","passage":"The recently observed gamma ray burst GRB 230307A lasted for 200 seconds, ______ for a burst generated by the merger of neutron stars. Bursts caused by neutron mergers typically last fewer than 2 seconds.","passage_lines":[{"type":"line","text":"The recently observed gamma ray burst GRB 230307A lasted for 200 seconds, ______ for a burst generated by the merger of neutron stars.","indent":0},{"type":"line","text":"Bursts caused by neutron mergers typically last fewer than 2 seconds.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["a coincidence","a reprieve","an incident","an oddity"]},{"id":"2390e956","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Easy","context":"Craft and Structure · Words in Context","passage":"Ronyoung Kim creatively captures the Korean American immigrant experience in her novel Clay Walls by writing about a family from three ______ perspectives. The first section of the novel is from the mother Haesu’s perspective, the second is from the father Chun’s perspective, and the last is from the daughter Faye’s perspective.","passage_lines":[{"type":"line","text":"Ronyoung Kim creatively captures the Korean American immigrant experience in her novel Clay Walls by writing about a family from three ______","indent":0},{"type":"line","text":"perspectives. The first section of the novel is from the mother Haesu’s perspective, the second is from the father Chun’s perspective, and the last","indent":0},{"type":"line","text":"is from the daughter Faye’s perspective.","indent":0}],"question":"Which choice completes the text with the most logical and precise word?","choices":["distinct","required","unintended","unknown"]},{"id":"d91e5499","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Easy","context":"Craft and Structure · Words in Context","passage":"A team of paleontologists has found a rich fossil deposit near Gulgong, Australia. The fossils are so well preserved that the team has been able to ______ detailed information about the life forms that left them behind, such as color patterns and how they interacted with other species.","passage_lines":[{"type":"line","text":"A team of paleontologists has found a rich fossil deposit near Gulgong, Australia. The fossils are so well preserved that the team has been able","indent":0},{"type":"line","text":"to ______ detailed information about the life forms that left them behind, such as color patterns and how they interacted with other species.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["occupy","hoard","reserve","obtain"]},{"id":"428cd2c1","domain":"Craft and Structure","skill":"Words in Context","difficulty":"Easy","context":"Craft and Structure · Words in Context","passage":"Some people have speculated that two helmets with attached horns discovered in Denmark in 1942 belonged to Vikings, but scholars have long been skeptical. Archaeologist Helle Vandkilde and colleagues recently provided radiocarbon dates for the helmets, and their findings ______ scholars’ skepticism: the helmets date to the Nordic Bronze Age, centuries before the Vikings existed.","passage_lines":[{"type":"line","text":"Some people have speculated that two helmets with attached horns discovered in Denmark in 1942 belonged to Vikings, but scholars have long","indent":0},{"type":"line","text":"been skeptical. Archaeologist Helle Vandkilde and colleagues recently provided radiocarbon dates for the helmets, and their findings ______","indent":0},{"type":"line","text":"scholars’ skepticism: the helmets date to the Nordic Bronze Age, centuries before the Vikings existed.","indent":0}],"question":"Which choice completes the text with the most logical and precise word or phrase?","choices":["anticipate","inspect","reveal","justify"]}];
